 "content": "from collections import Counter, deque


def transform(grid):
    """Fill enclosed dominant-background cavities; even-by-even cavities become 2, others 7."""
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            region = []
            touches_edge = False
            while q:
                cr, cc = q.popleft()
                region.append((cr, cc))
                if cr in (0, h - 1) or cc in (0, w - 1):
                    touches_edge = True
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and not seen[nr][nc]
                            and grid[nr][nc] == background):
                        seen[nr][nc] = True
                        q.append((nr, nc))
            if not touches_edge:
                rows = [rr for rr, _ in region]
                cols = [cc for _, cc in region]
                height = max(rows) - min(rows) + 1
                width = max(cols) - min(cols) + 1
                fill = 2 if height % 2 == 0 and width % 2 == 0 else 7
                for rr, cc in region:
                    out[rr][cc] = fill
    return out
